  PRIMARY KEY (time_slot_id, track_id, role_id)
);
CREATE TABLE event_roles (
  event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  role_id  TEXT NOT NULL REFERENCES roles(id),
  PRIMARY KEY (event_id, role_id)
);
CREATE TABLE events (
  id                TEXT PRIMARY KEY,
  chapter_id        INTEGER NOT NULL,
  name              TEXT NOT NULL,
  date              TEXT NOT NULL,               -- YYYY-MM-DD
  start_time        TEXT NOT NULL CHECK (length(start_time) = 5),
  end_time          TEXT NOT NULL CHECK (length(end_time) = 5),
  step_min          INTEGER NOT NULL DEFAULT 60, -- 15 | 30 | 60
  tz                TEXT NOT NULL DEFAULT 'Asia/Tokyo',
  status            TEXT NOT NULL DEFAULT 'draft'
                      CHECK (status IN ('draft','open','closed','published','ended')),
  has_party         INTEGER NOT NULL DEFAULT 0,
  no_solo_newcomer  INTEGER NOT NULL DEFAULT 1,
  max_consecutive   INTEGER NOT NULL DEFAULT 4,
  seed              INTEGER NOT NULL,
  apply_token       TEXT NOT NULL UNIQUE,
  view_token        TEXT NOT NULL UNIQUE,
  created_by        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  deleted_at        TEXT
, revision_cursor INTEGER);
CREATE TABLE oidc_session (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL,
  access_token TEXT NOT NULL,
  refresh_token TEXT,
  id_token TEXT NOT NULL,
  access_token_expires_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE
);
CREATE TABLE phases (
  id         TEXT PRIMARY KEY,
  event_id   TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  from_time  TEXT NOT NULL,
  to_time    TEXT NOT NULL,
  sort_order INTEGER NOT NULL
);
CREATE TABLE revisions (
  id          TEXT PRIMARY KEY,
  event_id    TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  seq         INTEGER NOT NULL,          -- per-event sequence, 1-based
  label       TEXT NOT NULL,             -- "自動生成（シード 20261114）", "手動編集"
  actor       TEXT NOT NULL,             -- display name, captured at write time
  actor_id    TEXT,
  kind        TEXT NOT NULL CHECK (kind IN ('generate','edit','restore')),
  group_key   TEXT,                      -- merge key for consecutive edits; NULL = never merges
  snapshot    TEXT NOT NULL,             -- JSON: { v: 1, items: [{ a, s, t, r, l }, ...] }
  metrics     TEXT NOT NULL,             -- JSON: evaluate()'s Metrics, verbatim
  created_at  TEXT NOT NULL,
  UNIQUE (event_id, seq)
);
CREATE TABLE roles (
  id         TEXT PRIMARY KEY,
